def synthesize(tt):
    def g(x, y):
        return min(1, tt[0]*tropical_threshold(x,0,0)*tropical_threshold(y,0,0) + tt[1]*tropical_threshold(x,0,0)*tropical_threshold(y,1,1) + tt[2]*tropical_threshold(x,1,1)*tropical_threshold(y,0,0) + tt[3]*tropical_threshold(x,1,1)*tropical_threshold(y,1,1))
    return g

def gol_step(config):
    candidates = set()
    for p in config:
        candidates.add(p)
        for d in MOORE_OFFSETS:
            candidates.add((p[0]+d[0], p[1]+d[1]))
    return {p for p in candidates if (p in config and neighbor_count(config,p) in (2,3)) or (p not in config and neighbor_count(config,p) == 3)}
